+      transform: rotate(45deg);
+      background: rgba(124, 92, 255, 0.2);
+    }
+
+    .answer {
+      max-height: 0;
+      overflow: hidden;
+      color: var(--muted);
+      line-height: 1.7;
+      transition: max-height 220ms ease, opacity 220ms ease;
+      opacity: 0;
+    }
+
+    .example[open] .answer {
+      max-height: 240px;
+      opacity: 1;
+    }
+
+    .answer p {
+      margin: 0;
+      padding: 0 22px 22px;
+    }
+
+    .footer-note {
+      margin: 22px 0 0;
+      color: #7f8aa3;
+      text-align: center;
+      font-size: 0.95rem;
+    }
+
