+      },
+      {
+        question: "How can I keep my cat entertained indoors?",
+        answer: "Offer climbing spaces, scratching posts, puzzle feeders, window perches, rotating toys, and short daily play sessions that mimic hunting with chasing, pouncing, and catching."
+      }
+    ];
+
+    function Header() {
+      return `
