+            care, comfort, and everyday enrichment.
+          </p>
+        </section>
+      `;
+    }
+
+    function FAQItem(item, index) {
+      const answerId = `answer-${index}`;
+      const buttonId = `question-${index}`;
+
+      return `
+        <div class="example">
