      .answer p {
        padding: 0 18px 18px;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed or content, but purring can also be a self-soothing behavior when they are stressed, injured, or asking for attention."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most adult cats sleep around 12 to 16 hours a day. Kittens and senior cats may sleep even more because growth, recovery, and lower energy levels increase their rest needs."
      },
      {
        question: "Should indoor cats still visit the vet?",
        answer: "Yes. Indoor cats still need wellness exams, vaccines recommended by a veterinarian, dental checks, parasite prevention guidance, and help catching health issues early."
