      --panel: rgba(18, 22, 35, 0.86);
      --panel-strong: #171c2b;
      --text: #f3f6ff;
      --muted: #a6afc3;
      --accent: #9ad7ff;
      --accent-strong: #7c5cff;
      --border: rgba(255, 255, 255, 0.12);
      --shadow: rgba(0, 0, 0, 0.4);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at 12% 8%, rgba(124, 92, 255, 0.26), transparent 28rem),
        radial-gradient(circle at 82% 20%, rgba(154, 215, 255, 0.18), transparent 24rem),
        linear-gradient(135deg, #070910 0%, var(--bg) 48%, #101522 100%);
    }

    main {
      width: min(960px, calc(100% - 32px));
      margin: 0 auto;
      padding: 64px 0;
    }

    .hero {
      margin-bottom: 32px;
      text-align: center;
    }

    .eyebrow {
      display: inline-flex;
      gap: 8px;
      align-items: center;
      margin: 0 0 14px;
      padding: 7px 12px;
      border: 1px solid var(--border);
      border-radius: 999px;
      color: var(--accent);
      background: rgba(255, 255, 255, 0.05);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.4rem, 7vw, 5.8rem);
      line-height: 0.92;
      letter-spacing: -0.08em;
    }

    .intro {
      max-width: 680px;
      margin: 22px auto 0;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.18rem);
      line-height: 1.7;
    }

    .faq-card {
      position: relative;
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.035)), var(--panel);
      box-shadow: 0 26px 80px var(--shadow);
      backdrop-filter: blur(18px);
    }

    .faq-card::before {
      position: absolute;
      inset: 0 0 auto;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(154, 215, 255, 0.78), transparent);
      content: "";
    }

    .details {
      display: grid;
      gap: 14px;
      padding: clamp(18px, 3vw, 28px);
    }

    .example {
      border: 1px solid var(--border);
      border-radius: 20px;
      background: rgba(10, 13, 22, 0.58);
      transition: border-color 180ms ease, background 180ms ease, transform 180ms ease;
    }

    .example:hover {
      border-color: rgba(154, 215, 255, 0.36);
      background: rgba(18, 23, 36, 0.82);
      transform: translateY(-1px);
    }

    .question-button {
      display: flex;
      width: 100%;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 22px 22px;
      border: 0;
      color: inherit;
      background: transparent;
      font: inherit;
      text-align: left;
      cursor: pointer;
    }

    .question {
      font-size: clamp(1.04rem, 2vw, 1.22rem);
      font-weight: 760;
      letter-spacing: -0.02em;
    }

    .icon {
      display: grid;
      flex: 0 0 34px;
      width: 34px;
      height: 34px;
      place-items: center;
      border: 1px solid rgba(154, 215, 255, 0.35);
      border-radius: 50%;
      color: var(--accent);
      background: rgba(154, 215, 255, 0.08);
      font-size: 1.35rem;
      line-height: 1;
      transition: transform 180ms ease, background 180ms ease;
    }

    .example[open] .icon {
      transform: rotate(45deg);
      background: rgba(124, 92, 255, 0.2);
    }

    .answer {
      max-height: 0;
      overflow: hidden;
      color: var(--muted);
      line-height: 1.7;
      transition: max-height 220ms ease, opacity 220ms ease;
      opacity: 0;
    }

    .example[open] .answer {
      max-height: 240px;
      opacity: 1;
    }

    .answer p {
      margin: 0;
      padding: 0 22px 22px;
    }

    .footer-note {
      margin: 22px 0 0;
      color: #7f8aa3;
      text-align: center;
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 20px, 960px);
        padding: 36px 0;
      }

      .question-button {
        padding: 18px;
      }

      .answer p {
        padding: 0 18px 18px;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed or content, but purring can also be a self-soothing behavior when they are stressed, injured, or asking for attention."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most adult cats sleep around 12 to 16 hours a day. Kittens and senior cats may sleep even more because growth, recovery, and lower energy levels increase their rest needs."
      },
      {
        question: "Should indoor cats still visit the vet?",
        answer: "Yes. Indoor cats still need wellness exams, vaccines recommended by a veterinarian, dental checks, parasite prevention guidance, and help catching health issues early."
      },
      {
        question: "Why does my cat knead blankets or my lap?",
        answer: "Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead soft surfaces when they feel safe, affectionate, sleepy, or ready to settle in."
      },
      {
        question: "What is the best way to introduce two cats?",
        answer: "Go slowly: keep them separated at first, swap scents, use short supervised meetings, and reward calm behavior. Rushing introductions can make territorial stress worse."
      },
      {
        question: "How can I keep my cat entertained indoors?",
        answer: "Offer climbing spaces, scratching posts, puzzle feeders, window perches, rotating toys, and short daily play sessions that mimic hunting with chasing, pouncing, and catching."
      }
    ];

    function Header() {
      return `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Cat Companion Guide</p>
          <h1 id="page-title">FAQ about cats</h1>
          <p class="intro">
            Quick, practical answers to common questions about feline behavior,
            care, comfort, and everyday enrichment.
          </p>
        </section>
      `;
    }

    function FAQItem(item, index) {
      const answerId = `answer-${index}`;
      const buttonId = `question-${index}`;

      return `
        <div class="example">
          <button
            class="question-button"
            id="${buttonId}"
            type="button"
            aria-expanded="false"
            aria-controls="${answerId}"
          >
            <span class="question">${item.question}</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="answer" id="${answerId}" role="region" aria-labelledby="${buttonId}">
            <p>${item.answer}</p>
          </div>
        </div>
      `;
    }

    function FAQList(items) {
      return `
        <section class="faq-card" aria-label="Cat FAQ">
          <div class="details">
            ${items.map(FAQItem).join("")}
          </div>
        </section>
      `;
    }

    function App() {
      return `
        ${Header()}
        ${FAQList(faqs)}
        <p class="footer-note">Questions are collapsed by default. Tap a card to reveal the answer.</p>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.querySelectorAll(".example").forEach((item) => {
      const button = item.querySelector(".question-button");

      button.addEventListener("click", () => {
        const isOpen = item.hasAttribute("open");
        item.toggleAttribute("open", !isOpen);
        button.setAttribute("aria-expanded", String(!isOpen));
      });
    });
  </script>
</body>
</html>
